      sha256 "2751bbd628abba51f05dc0b75b21017249f42c06e73d6308082e0ffc689ac899"
    end
    on_intel do
      url "https://blindpass.app/cli/0.2.77/blindpass-0.2.77-linux-x64.tar.gz"
